SELECT 
    (
        SUM(CASE WHEN status = 'A' THEN amount ELSE 0 END) * 100.0 / 
        SUM(amount)
    ) AS percentage_paid_no_issue
FROM loan;

SELECT id, (SELECT COUNT(*) FROM cards WHERE borderColor = 'black') AS black_border_count
FROM cards
WHERE borderColor = 'black';

SELECT DisplayName, Age
FROM users
WHERE Views = (
    SELECT MAX(Views)
    FROM users
);

SELECT 
    (SELECT COUNT(*) FROM posts WHERE OwnerUserId = (SELECT Id FROM users ORDER BY CreationDate DESC LIMIT 1)) AS post_count,
    (SELECT COUNT(*) FROM comments WHERE UserId = (SELECT Id FROM users ORDER BY CreationDate DESC LIMIT 1)) AS comment_count;

SELECT id
FROM superpower
WHERE power_name = 'cryokinesis';
